INSERT INTO public.blitz_questions(topic,question,options,correct_index,legal_act,article,source_url,explanation,verified) VALUES
('Антимонопольное регулирование','Какой признак отличает конкуренцию в смысле закона № 135-ФЗ?','["Участники заранее совместно устанавливают цены","Государство назначает каждому продавцу квоту","Самостоятельные действия хозяйствующих субъектов ограничивают возможность односторонне влиять на условия обращения товаров","Все организации обязаны иметь равные доли рынка"]'::jsonb,2,'ФЗ от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_61763/baabe5b69a3c031bfb8d485891bf8077d6809a94/','Ответ следует из действующей статьи 4 закона № 135-ФЗ: Самостоятельные действия хозяйствующих субъектов ограничивают возможность односторонне влиять на условия обращения товаров.',true),
('Антимонопольное регулирование','Относится ли выполнение работ и оказание услуг к понятию товара для целей закона № 135-ФЗ?','["Да","Нет"]'::jsonb,0,'ФЗ от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_61763/baabe5b69a3c031bfb8d485891bf8077d6809a94/','Ответ следует из действующей статьи 4 закона № 135-ФЗ: Да.',true),
('Антимонопольное регулирование','Какой признак определяет взаимозаменяемые товары для целей защиты конкуренции?','["Они продаются только одним продавцом","Их марки обязаны совпадать","Их производят на территории одного региона","Покупатель готов заменить один товар другим при потреблении"]'::jsonb,3,'ФЗ от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_61763/baabe5b69a3c031bfb8d485891bf8077d6809a94/','Ответ следует из действующей статьи 4 закона № 135-ФЗ: Покупатель готов заменить один товар другим при потреблении.',true),
('Антимонопольное регулирование','Что означает сетевой эффект применительно к цифровой платформе?','["Обязательную регистрацию платформы в государственном реестре","Изменение ценности платформы в зависимости от числа покупателей и продавцов","Постоянство стоимости услуги при любом спросе","Техническое отсутствие доступа к конкурентам"]'::jsonb,1,'ФЗ от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_61763/baabe5b69a3c031bfb8d485891bf8077d6809a94/','Ответ следует из действующей статьи 4 закона № 135-ФЗ: Изменение ценности платформы в зависимости от числа покупателей и продавцов.',true),
('Антимонопольное регулирование','Какова правовая характеристика недобросовестной конкуренции?','["Любое снижение цены независимо от обстоятельств","Любая рекламная кампания","Действия ради преимуществ, противоречащие закону или добропорядочности и способные причинить вред конкуренту","Любая победа при государственных закупках"]'::jsonb,2,'ФЗ от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_61763/baabe5b69a3c031bfb8d485891bf8077d6809a94/','Ответ следует из действующей статьи 4 закона № 135-ФЗ: Действия ради преимуществ, противоречащие закону или добропорядочности и способные причинить вред конкуренту.',true),
('Антимонопольное регулирование','Считается ли экономической концентрацией сделка, способная повлиять на состояние конкуренции?','["Да","Нет"]'::jsonb,0,'ФЗ от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_61763/baabe5b69a3c031bfb8d485891bf8077d6809a94/','Ответ следует из действующей статьи 4 закона № 135-ФЗ: Да.',true),
('Антимонопольное регулирование','Что означает термин «дискриминационные условия» на товарном рынке?','["Любое отличие продукции по качеству","Обязательную форму государственной собственности","Законное различие налоговых ставок по территориям","Неравное положение одних хозяйствующих субъектов относительно других в условиях доступа или обращения товара"]'::jsonb,3,'ФЗ от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_61763/baabe5b69a3c031bfb8d485891bf8077d6809a94/','Ответ следует из действующей статьи 4 закона № 135-ФЗ: Неравное положение одних хозяйствующих субъектов относительно других в условиях доступа или обращения товара.',true),
('Антимонопольное регулирование','Что входит в понятие монополистической деятельности?','["Только создание федеральных министерств","Злоупотребление доминированием и запрещённые антиконкурентные соглашения или действия","Любое повышение заработной платы работников","Любая разработка нового товара"]'::jsonb,1,'ФЗ от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_61763/baabe5b69a3c031bfb8d485891bf8077d6809a94/','Ответ следует из действующей статьи 4 закона № 135-ФЗ: Злоупотребление доминированием и запрещённые антиконкурентные соглашения или действия.',true),
('Антимонопольное регулирование','Может ли злоупотребление доминирующим положением выражаться в бездействии?','["Да","Нет"]'::jsonb,0,'ФЗ от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 10','https://www.consultant.ru/document/cons_doc_LAW_61763/851f7a5f6d99da11639600f4c686a2949ab23feb/','Ответ следует из действующей статьи 10 закона № 135-ФЗ: Да.',true),
('Антимонопольное регулирование','Является ли ущемление интересов неопределённого круга потребителей возможным основанием нарушения статьи 10 закона № 135-ФЗ?','["Да","Нет"]'::jsonb,0,'ФЗ от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 10','https://www.consultant.ru/document/cons_doc_LAW_61763/851f7a5f6d99da11639600f4c686a2949ab23feb/','Ответ следует из действующей статьи 10 закона № 135-ФЗ: Да.',true),
('Антимонопольное регулирование','Какое поведение доминирующего субъекта может подпадать под запрет статьи 10?','["Законное повышение квалификации работников","Навязывание контрагенту невыгодных или не относящихся к предмету договора условий","Добровольное снижение издержек производства","Публикация обязательной бухгалтерской отчётности"]'::jsonb,1,'ФЗ от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 10','https://www.consultant.ru/document/cons_doc_LAW_61763/851f7a5f6d99da11639600f4c686a2949ab23feb/','Ответ следует из действующей статьи 10 закона № 135-ФЗ: Навязывание контрагенту невыгодных или не относящихся к предмету договора условий.',true),
('Антимонопольное регулирование','Запрещено ли доминирующему субъекту без экономического обоснования создавать препятствия доступу на товарный рынок другим хозяйствующим субъектам?','["Да","Нет"]'::jsonb,0,'ФЗ от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 10','https://www.consultant.ru/document/cons_doc_LAW_61763/851f7a5f6d99da11639600f4c686a2949ab23feb/','Ответ следует из действующей статьи 10 закона № 135-ФЗ: Да.',true),
('Антимонопольное регулирование','Какой вариант относится к злоупотреблению доминированием при выполнении условий статьи 10?','["Участие в отраслевой выставке","Предоставление открытой информации потребителям","Создание дискриминационных условий","Повышение производительности труда"]'::jsonb,2,'ФЗ от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 10','https://www.consultant.ru/document/cons_doc_LAW_61763/851f7a5f6d99da11639600f4c686a2949ab23feb/','Ответ следует из действующей статьи 10 закона № 135-ФЗ: Создание дискриминационных условий.',true),
('Антимонопольное регулирование','Допускается ли признание монополистической деятельностью не только соглашений, но и согласованных действий в установленных законом случаях?','["Да","Нет"]'::jsonb,0,'ФЗ от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_61763/baabe5b69a3c031bfb8d485891bf8077d6809a94/','Ответ следует из действующей статьи 4 закона № 135-ФЗ: Да.',true),
('Антимонопольное регулирование','Является ли предоставление финансовых услуг отдельной категорией в понятийном аппарате закона № 135-ФЗ?','["Да","Нет"]'::jsonb,0,'ФЗ от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_61763/baabe5b69a3c031bfb8d485891bf8077d6809a94/','Ответ следует из действующей статьи 4 закона № 135-ФЗ: Да.',true)
